// Entscheidet, ob dieser Besuch einen Anruf wert ist.
//
// Das Problem, das der Filter loest: ipinfo liefert bei einem Privatanschluss
// den PROVIDER, nicht die Firma des Besuchers — "AS3320 Deutsche Telekom AG"
// heisst nur, dass jemand einen Telekom-Anschluss hat. Bei einem Firmennetz mit
// eigenem AS steht dort dagegen der echte Name.
//
// Gemeldet wird deshalb nur, was uebrig bleibt, wenn man Provider, Mobilfunk
// und Rechenzentren abzieht.

const d = $input.first().json;

// ── Was immer gemeldet wird: jemand sucht gerade aktiv Kontakt ──────────────
const HARTE_SIGNALE = ['telefon_geklickt', 'email_geklickt', 'popup_geklickt',
                       'termin_geoeffnet', 'selbstcheck_fertig'];

if (HARTE_SIGNALE.includes(d.ereignis)) {
  return [{ json: { ...d, melden: true, grund: 'Kontaktsignal' } }];
}

// Alles ausser einem Besuch faellt hier raus (z. B. der Tagesbericht).
if (d.ereignis !== 'besuch') {
  return [{ json: { ...d, melden: false, grund: 'kein Besuch, kein Kontaktsignal' } }];
}

// ── Ohne Firmenkennung gibt es nichts anzurufen ─────────────────────────────
if (!d.firma) {
  return [{ json: { ...d, melden: false, grund: 'keine Firma erkannt' } }];
}

// ── Provider, Mobilfunk, Carrier: das ist ein Privatanschluss ───────────────
const PRIVAT = [
  'deutsche telekom', 'telekom deutschland', 'vodafone', 'telefonica', 'o2 ',
  '1&1', 'united internet', 'kabel deutschland', 'unitymedia', 'netcologne',
  'ewe tel', 'm-net', 'wilhelm.tel', 'htp gmbh', 'osnatel', 'versatel',
  'plusnet', 'pyur', 'tele columbus', 'congstar', 'drillisch', 'freenet',
  'colt technology', 'telenet', 'liberty global', 'orange', 'proximus',
  'swisscom', 'a1 telekom', 'magenta telekom', 'init7', 'sunrise',
];

// ── Rechenzentren und Cloud: das ist ein Bot oder ein VPN ───────────────────
const MASCHINEN = [
  'amazon', 'aws', 'google llc', 'google cloud', 'microsoft', 'azure',
  'hetzner', 'ovh', 'digitalocean', 'linode', 'vultr', 'cloudflare',
  'akamai', 'fastly', 'contabo', 'ionos', 'strato', 'netcup', 'scaleway',
  'oracle', 'alibaba', 'tencent', 'datacamp', 'm247', 'leaseweb',
  'nordvpn', 'mullvad', 'private internet', 'surfshark', 'protonvpn',
];

const firma = String(d.firma).toLowerCase();

for (const wort of PRIVAT) {
  if (firma.includes(wort)) {
    return [{ json: { ...d, melden: false, grund: `Privatanschluss (${wort})` } }];
  }
}
for (const wort of MASCHINEN) {
  if (firma.includes(wort)) {
    return [{ json: { ...d, melden: false, grund: `Rechenzentrum oder VPN (${wort})` } }];
  }
}

// Was hier ankommt, ist ein Firmennetz mit eigenem Eintrag.
return [{ json: { ...d, melden: true, grund: 'Firmennetz' } }];

// Baut die Nachricht — geschrieben fuer jemanden, der gleich anruft.
//
// Oben steht, WER es ist. Darunter, WAS er angesehen hat. Ganz unten die
// Herkunft, falls es aus einer Kampagne kam.

const TITEL = {
  besuch: 'Firma auf der Website',
  termin_geoeffnet: 'Terminseite geoeffnet',
  popup_geklickt: 'Popup geklickt — will einen Call',
  telefon_geklickt: 'Telefonnummer geklickt',
  email_geklickt: 'E-Mail-Adresse geklickt',
  selbstcheck_fertig: 'Selbstcheck abgeschlossen',
};

const d = $input.first().json;

// Der Tagesbericht bringt seinen Text schon fertig mit.
if (d.text) {
  return [{ json: { betreff: 'KITech-Website: Tagesbericht', nachricht: d.text, roh: d } }];
}

const firma = d.firma ? String(d.firma).replace(/^AS\d+\s+/, '') : null;

const kopf = firma ? firma : (TITEL[d.ereignis] ?? d.ereignis);
const betreff = firma
  ? `Website-Besuch: ${firma}`
  : `Website: ${TITEL[d.ereignis] ?? d.ereignis}`;

const zeilen = [];
zeilen.push(kopf);
zeilen.push('');

if (firma) {
  const ortsteil = [d.ort, d.region].filter(Boolean).join(', ');
  if (ortsteil) zeilen.push(`Sitz laut Netz: ${ortsteil}`);
}

zeilen.push(`Was: ${TITEL[d.ereignis] ?? d.ereignis}`);
if (d.seite) zeilen.push(`Seite: ${d.seite}`);

if (d.referrer) zeilen.push(`Kam ueber: ${d.referrer}`);

const kampagne = [d.utm_source, d.utm_medium, d.utm_campaign].filter(Boolean).join(' / ');
if (kampagne) zeilen.push(`Kampagne: ${kampagne}`);

if (d.zeitpunkt) {
  zeilen.push('');
  zeilen.push(new Date(d.zeitpunkt).toLocaleString('de-DE', { timeZone: 'Europe/Berlin' }));
}

if (firma) {
  zeilen.push('');
  zeilen.push(`Suche: https://www.google.com/search?q=${encodeURIComponent(firma)}`);
}

return [{ json: { betreff, nachricht: zeilen.join('\n'), roh: d } }];
